async function actualLegacyEngine(f:Awaited<ReturnType<typeof seedLine>>){
 storage.clear();producer.writes=[];producer.auth.currentUser={uid:actor.uid,getIdTokenResult:async()=>({claims:actor.token})};
 const order:any={...(await db.doc(f.order).get()).data(),id:f.intent.orderId};const catalog=await db.runTransaction(tx=>assembleOrderProductionCatalogInputs(tx,db,{companyId:'taebaek',policyVersion:SERVER_PREVIEW_POLICY}));if(catalog.status!=='assembled')throw Error(catalog.reason);
 const engine=createOrderStockEngine({db:{}as any,allItems:catalog.allItems as any,submaterials:[],partners:[],orders:[order as any],allOrders:[order as any],orderUnitInputs:catalog.inputs as any,buildFormula:catalog.buildFormula,actorName:'합성 직원',getActorUid:()=>actor.uid,retireRetainedRequestBeforeClaim:async()=>undefined,claimOrderOperation:(orderId,expectedStatus,operation,referenceGuard)=>claimOrderInventoryOperation(orderId,expectedStatus,operation,undefined,referenceGuard),createProductionRecordsForOrder:async()=>{throw Error('legacy generation 우회금지');},createProductionRecordPlan:(order,inputs,generation)=>buildOrderProductionRecordPlan(order as any,catalog.allItems,inputs!,generation,{dateOf:iso=>(iso??generation.startedAt).slice(0,10)}),updateItem:async(collection,id,patch)=>{const path=collection+'/'+id;own(path);await db.doc(path).update(patch);},addItem:async(collection,data)=>{const path=collection+'/'+(data.id??prefix+'audit-'+producer.writes.length);own(path);await db.doc(path).set(data);}});
 return {engine,order};
}
async function legacyToggle(f:Awaited<ReturnType<typeof seedLine>>,index:number,checked:boolean){const {engine,order}=await actualLegacyEngine(f),rows=order.items!.map((row:any,i:number)=>i===index?{...row,checked,...(checked?{checkedBy:'합성 직원',checkedAt:new Date().toISOString()}:{} )}:row);await engine.changeOrderItemCompletion(f.intent.orderId,index,rows as any,checked?'DISPATCHED' as any:'PENDING' as any);const current=(await db.doc(f.order).get()).data()!;expect(current.inventoryOperation).toBeNull();expect(current.itemInventory[rows[index].lineId].applied).toBe(checked);expect(hasOrderInventoryGenerationCompletion({...current,id:f.intent.orderId} as any,current.inventoryGenerationCompletion.generation)).toBe(true);return current;}
